def merge_overlapping_intervals(intervals):
    if not intervals:
        return []
    s = sorted(intervals, key=lambda p: p[0])
    out = [list(s[0])]
    for start, end in s[1:]:
        if start <= out[-1][1]:
            out[-1][1] = max(out[-1][1], end)
        else:
            out.append([start, end])
    return [tuple(x) for x in out]

